const __pageData = JSON.parse('{"title":"DNS 解析工程实践：递归查询、缓存与故障治理","description":"","frontmatter":{"title":"DNS 解析工程实践：递归查询、缓存与故障治理","date":"2026-08-12T00:00:00.000Z","category":"后端开发","cover":"/covers/backend.svg","tags":["dns","network","java","cache","reliability"],"excerpt":"从一次域名查询出发，讲清 Stub Resolver、递归与迭代查询、权威数据、正负缓存和 Java 地址缓存，并给出超时隔离、切流发布与可观测性实践。"},"headers":[],"relativePath":"posts/dns-resolution-cache-engineering.md","filePath":"posts/dns-resolution-cache-engineering.md","lastUpdated":1786525990000}');
